SELECT w.*,o.phase AS owner_phase,o.held_rows AS owner_held_rows,o.held_bytes AS owner_held_bytes,o.peak_rows AS owner_peak_rows,o.peak_bytes AS owner_peak_bytes,o.removed_rows AS owner_removed_rows,o.removed_bytes AS owner_removed_bytes FROM {s}.init_operation o LEFT JOIN LATERAL (SELECT 1 AS present,position,host_path FROM (SELECT position,host_path,sum(octet_length(host_path)+8) OVER (ORDER BY position) AS run,row_number() OVER (ORDER BY position) AS n FROM (SELECT position,host_path FROM {s}.init_entry WHERE operation_id=$1::bigint AND kind=2 AND position>$3::bigint ORDER BY position LIMIT $4::bigint) l) j WHERE n=1 OR run<=$5::bigint) w ON true WHERE o.operation_id=$1::bigint AND o.owner_epoch=$2::bigint
